      es: 'Separador autoestático con un marco metálico y dos (o tres) hojas laterales que se bloquean con una cremallera central.',
      en: 'Self-retaining retractor with a metal frame and two (or three) lateral blades locked in place by a central ratchet.',
    ),
    use: LocalizedText(
      ca: 'Exposició de la cavitat abdominal en laparotomies (histerectomia, cesària, cirurgia gàstrica i intestinal), sense necessitat d\'ajudant.',
      es: 'Exposición de la cavidad abdominal en laparotomías (histerectomía, cesárea, cirugía gástrica e intestinal), sin necesidad de ayudante.',
      en: 'Exposing the abdominal cavity in laparotomies (hysterectomy, cesarean section, gastric and bowel surgery), without needing an assistant to hold retraction.',
    ),
    tip: LocalizedText(
      ca: 'A diferència del separador de Bookwalter, no es fixa a la taula d\'operacions, cosa que el fa més ràpid de col·locar però amb menys exposició en pacients obesos.',
      es: 'A diferencia del separador de Bookwalter, no se fija a la mesa de operaciones, lo que lo hace más rápido de colocar pero con menos exposición en pacientes obesos.',
      en: 'Unlike the Bookwalter retractor, it does not attach to the operating table, making it quicker to set up but giving less exposure in obese patients.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/a9/Surgical_retractor.jpg',
      license: 'CC0 1.0',
      attribution: 'Saltanat ebli, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Surgical_retractor.jpg',
    ),
