  Instrument(
    id: 'separador-deaver',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Deaver', es: 'Separador de Deaver', en: 'Deaver retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Deaver retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador manual amb una fulla llarga i corba, en forma d\'interrogant, de superfície llisa.',
      es: 'Separador manual con una hoja larga y curva, en forma de interrogante, de superficie lisa.',
      en: 'Handheld retractor with a long, smoothly curved, question-mark-shaped blade.',
    ),
    use: LocalizedText(
      ca: 'Retracció profunda de vísceres i paret abdominal (fetge, estómac, intestí) en cirurgia oberta abdominal i toràcica; per exemple en colecistectomia o colectomia obertes.',
      es: 'Retracción profunda de vísceras y pared abdominal (hígado, estómago, intestino) en cirugía abierta abdominal y torácica; por ejemplo en colecistectomía o colectomía abiertas.',
      en: 'Deep retraction of viscera and the abdominal wall (liver, stomach, bowel) in open abdominal and thoracic surgery; for example, in open cholecystectomy or colectomy.',
    ),
    tip: LocalizedText(
      ca: 'El mànec pla acaba en un ganxo on l\'ajudant pot recolzar un dit per reduir la fatiga durant estones llargues de retracció.',
      es: 'El mango plano termina en un gancho donde el ayudante puede apoyar un dedo para reducir la fatiga durante tramos largos de retracción.',
      en: 'The flat handle ends in a hook where the assistant can rest a finger to reduce fatigue during long periods of retraction.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/8/86/Deaver_retractor_01.JPG',
      license: 'CC0 1.0',
      attribution: 'Saltanat ebli, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Deaver_retractor_01.JPG',
    ),
  ),
  Instrument(
    id: 'separador-maleable',
    isNew: true,
    name: LocalizedText(ca: 'Separador maleable', es: 'Separador maleable', en: 'Malleable retractor'),
    category: InstrumentCategory.separacion,
    aliases: ['Ribbon retractor', 'Malleable ribbon retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Fulla metàl·lica llarga, prima i plana, sense forma fixa: es doblega manualment a la forma que calgui durant la intervenció.',
      es: 'Hoja metálica larga, fina y plana, sin forma fija: se dobla manualmente según la forma que se necesite durante la intervención.',
      en: 'Long, thin, flat metal blade with no fixed shape: it is manually bent into whatever shape is needed during the operation.',
    ),
    use: LocalizedText(
      ca: 'Protecció i retracció suau d\'òrgans i intestí en cirurgia abdominal oberta, quan cap separador prefabricat s\'adapta a l\'angle necessari.',
      es: 'Protección y retracción suave de órganos e intestino en cirugía abdominal abierta, cuando ningún separador prefabricado se adapta al ángulo necesario.',
      en: 'Gentle protection and retraction of organs and bowel in open abdominal surgery, when no preformed retractor fits the angle needed.',
    ),
    tip: LocalizedText(
      ca: 'Com que és prim i flexible, cal un recompte acurat en tancar: la literatura ha descrit casos de separadors maleables oblidats a la cavitat abdominal.',
      es: 'Al ser fino y flexible, requiere un recuento cuidadoso al cerrar: la literatura ha descrito casos de separadores maleables olvidados en la cavidad abdominal.',
      en: 'Being thin and flexible, it requires a careful instrument count at closure: the literature has reported cases of malleable retractors left behind in the abdominal cavity.',
    ),
  ),
  Instrument(
    id: 'aguja-veress',
    isNew: true,
    name: LocalizedText(ca: 'Agulla de Veress', es: 'Aguja de Veress', en: 'Veress needle'),
    category: InstrumentCategory.especiales,
    aliases: ['Veress needle', 'Verres needle'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Agulla llarga amb una cànula externa de punta esbiaixada i un fiador intern retràctil, amb molla, que sobresurt en entrar en una cavitat sense resistència.',
      es: 'Aguja larga con una cánula externa de punta biselada y un fiador interno retráctil, con resorte, que sobresale al entrar en una cavidad sin resistencia.',
      en: 'Long needle with a beveled-tip outer cannula and a spring-loaded, retractable inner stylet that springs forward on entering a cavity with no resistance.',
    ),
    use: LocalizedText(
      ca: 'Creació del pneumoperitoneu insuflant CO2 a la cavitat abdominal abans de l\'entrada amb tròcar, en la tècnica laparoscòpica tancada.',
      es: 'Creación del neumoperitoneo insuflando CO2 en la cavidad abdominal antes de la entrada con trocar, en la técnica laparoscópica cerrada.',
      en: 'Creating the pneumoperitoneum by insufflating CO2 into the abdominal cavity before trocar entry, in the closed laparoscopic technique.',
    ),
    tip: LocalizedText(
      ca: 'El clic de la molla en travessar el peritoneu i una prova d\'aspiració negativa (test de la gota de sèrum) ajuden a confirmar la posició correcta abans d\'insuflar.',
      es: 'El clic del resorte al atravesar el peritoneo y una prueba de aspiración negativa (test de la gota de suero) ayudan a confirmar la posición correcta antes de insuflar.',
      en: 'The click of the spring as it crosses the peritoneum, together with a negative-aspiration check (the saline drop test), helps confirm correct placement before insufflating.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/55/Verres_Needle.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Lx zander, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Verres_Needle.jpg',
    ),
  ),
  Instrument(
    id: 'pinza-intestinal-doyen',
    isNew: true,
    name: LocalizedText(ca: 'Pinça intestinal de Doyen', es: 'Pinza intestinal de Doyen', en: 'Doyen intestinal forceps'),
    category: InstrumentCategory.diseccion,
    aliases: ['Doyen intestinal clamp', 'Doyen bowel clamp'],
    icon: 'pinch',
    description: LocalizedText(
      ca: 'Pinça llarga, recta o corba, de branques flexibles amb estries longitudinals i sense dents; instrument diferent de la valva de Doyen (que és un separador), tot i compartir el mateix epònim.',
      es: 'Pinza larga, recta o curva, de ramas flexibles con estrías longitudinales y sin dientes; instrumento distinto de la valva de Doyen (que es un separador), aunque comparta el mismo epónimo.',
      en: 'Long, straight or curved forceps with flexible, longitudinally serrated, toothless jaws; a different instrument from the Doyen retractor (valve), despite sharing the same eponym.',
    ),
    use: LocalizedText(
      ca: 'Oclusió atraumàtica i temporal de la llum intestinal per evitar vessament de contingut durant una resecció o anastomosi.',
      es: 'Oclusión atraumática y temporal de la luz intestinal para evitar el derrame de contenido durante una resección o anastomosis.',
      en: 'Atraumatic, temporary occlusion of the bowel lumen to prevent spillage of contents during resection or anastomosis.',
    ),
    tip: LocalizedText(
      ca: 'Les branques flexibles reparteixen la pressió de manera uniforme sobre la paret intestinal, evitant aixafar-la fins i tot en clampar amb fermesa.',
      es: 'Las ramas flexibles reparten la presión de forma uniforme sobre la pared intestinal, evitando aplastarla incluso al clampar con firmeza.',
      en: 'The flexible jaws distribute pressure evenly across the bowel wall, avoiding crushing it even when clamped firmly.',
    ),
  ),
  Instrument(
    id: 'grapadora-lineal-corte',
    isNew: true,
    name: LocalizedText(ca: 'Grapadora lineal de tall', es: 'Grapadora lineal de corte', en: 'Linear cutting stapler'),
    category: InstrumentCategory.sutura,
    aliases: ['GIA stapler', 'Linear cutter', 'Endo GIA (Medtronic)'],
    icon: 'needle',
    description: LocalizedText(
      ca: 'Dispositiu mecànic que aplica dues o més files paral·leles de grapes de titani o acer i talla el teixit entre elles en un sol tret; existeix en versió oberta i laparoscòpica, reutilitzable (amb càrregues) o d\'un sol ús.',
      es: 'Dispositivo mecánico que aplica dos o más filas paralelas de grapas de titanio o acero y corta el tejido entre ellas en un solo disparo; existe en versión abierta y laparoscópica, reutilizable (con cargas) o de un solo uso.',
      en: 'Mechanical device that fires two or more parallel rows of titanium or steel staples and cuts the tissue between them in a single stroke; available in open and laparoscopic versions, either reloadable or single-use.',
    ),
    use: LocalizedText(
      ca: 'Secció i tancament simultani d\'intestí, estómac o pulmó en reseccions (per exemple, gastrectomia en mànega, resecció intestinal, resecció pulmonar) i en la confecció d\'anastomosis latero-laterals.',
      es: 'Sección y cierre simultáneo de intestino, estómago o pulmón en resecciones (por ejemplo, gastrectomía en manga, resección intestinal, resección pulmonar) y en la confección de anastomosis latero-laterales.',
      en: 'Simultaneous transection and closure of bowel, stomach or lung during resections (for example, sleeve gastrectomy, bowel resection, lung resection) and when constructing side-to-side anastomoses.',
    ),
    tip: LocalizedText(
      ca: 'A diferència de plataformes motoritzades com la Signia, la majoria de grapadores lineals són d\'accionament manual i d\'un sol ús, i són les més habituals a la majoria de quiròfans.',
      es: 'A diferencia de plataformas motorizadas como la Signia, la mayoría de grapadoras lineales son de accionamiento manual y de un solo uso, y son las más habituales en la mayoría de quirófanos.',
      en: 'Unlike motorized platforms such as Signia, most linear staplers are manually fired and single-use, and are the type most commonly found in everyday operating rooms.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/4/4a/Surgical_stapler_%26_cutter_linear.JPG',
      license: 'CC BY-SA 3.0',
      attribution: 'Ignis, Wikimedia Commons',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Surgical_stapler_%26_cutter_linear.JPG',
    ),
  ),
  Instrument(
    id: 'drenaje-penrose',
    isNew: true,
    name: LocalizedText(ca: 'Dren de Penrose', es: 'Drenaje de Penrose', en: 'Penrose drain'),
    category: InstrumentCategory.especiales,
    aliases: ['Penrose drain'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub de cautxú tou, pla i flexible, obert pels dos extrems, sense cap sistema de succió.',
      es: 'Tubo de caucho blando, plano y flexible, abierto por los dos extremos, sin ningún sistema de succión.',
      en: 'Soft, flat, flexible rubber tube, open at both ends, with no suction system.',
    ),
    use: LocalizedText(
      ca: 'Drenatge passiu per capil·laritat i gravetat de líquid o pus d\'una ferida o cavitat, evitant-ne l\'acumulació sota la pell.',
      es: 'Drenaje pasivo por capilaridad y gravedad de líquido o pus de una herida o cavidad, evitando su acumulación bajo la piel.',
      en: 'Passive drainage of fluid or pus from a wound or cavity by capillary action and gravity, preventing its build-up under the skin.',
    ),
    tip: LocalizedText(
      ca: 'Sovint es fixa amb un imperdible o un punt a la pell perquè no s\'introdueixi cap a l\'interior de la ferida.',
      es: 'A menudo se fija con un imperdible o un punto en la piel para que no se introduzca hacia el interior de la herida.',
      en: 'It is often secured with a safety pin or a skin stitch so it does not slip back inside the wound.',
    ),
  ),
  Instrument(
    id: 'drenaje-jackson-pratt',
    isNew: true,
    name: LocalizedText(ca: 'Dren de Jackson-Pratt (JP)', es: 'Drenaje de Jackson-Pratt (JP)', en: 'Jackson-Pratt drain (JP)'),
    category: InstrumentCategory.especiales,
    aliases: ['JP drain', 'Jackson-Pratt drain'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema de drenatge tancat format per un tub intern multiperforat connectat, mitjançant un tub de plàstic, a una ampolla o bulb flexible en forma de granada.',
      es: 'Sistema de drenaje cerrado formado por un tubo interno multiperforado conectado, mediante un tubo de plástico, a una ampolla o bulbo flexible en forma de granada.',
      en: 'Closed-suction drainage system made of a perforated internal tube connected by plastic tubing to a flexible, grenade-shaped bulb.',
    ),
    use: LocalizedText(
      ca: 'Evacuació activa de líquid d\'un espai mort postquirúrgic (per exemple, després d\'una mastectomia, tiroïdectomia o cirurgia abdominal), evitant seromes o hematomes.',
      es: 'Evacuación activa de líquido de un espacio muerto postquirúrgico (por ejemplo, tras una mastectomía, tiroidectomía o cirugía abdominal), evitando seromas o hematomas.',
      en: 'Active evacuation of fluid from a postoperative dead space (for example, after mastectomy, thyroidectomy or abdominal surgery), preventing seromas or hematomas.',
    ),
    tip: LocalizedText(
      ca: 'El buit es crea comprimint el bulb abans de tancar el tap: convé buidar-lo abans que s\'ompli més de la meitat perquè mantingui una succió eficaç.',
      es: 'El vacío se crea comprimiendo el bulbo antes de cerrar el tapón: conviene vaciarlo antes de que se llene más de la mitad para que mantenga una succión eficaz.',
      en: 'The vacuum is created by compressing the bulb before closing its plug: it should be emptied before it is more than half full so it keeps suctioning effectively.',
    ),
  ),
  Instrument(
    id: 'drenaje-kehr',
    isNew: true,
    name: LocalizedText(ca: 'Tub en T (de Kehr)', es: 'Tubo en T (de Kehr)', en: 'T-tube (Kehr tube)'),
    category: InstrumentCategory.especiales,
    aliases: ['Kehr T-tube', 'Biliary T-tube'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub de goma o silicona amb forma de T: el braç curt transversal queda dins el conducte biliar i el braç llarg surt a través de la pell.',
      es: 'Tubo de goma o silicona con forma de T: el brazo corto transversal queda dentro del conducto biliar y el brazo largo sale a través de la piel.',
      en: 'Rubber or silicone tube shaped like the letter T: the short crossbar sits inside the bile duct while the long limb exits through the skin.',
    ),
    use: LocalizedText(
      ca: 'Drenatge temporal de la via biliar principal després d\'una coledocotomia (extracció de càlculs del colèdoc), deixant una via d\'accés per fer una colangiografia postoperatòria.',
      es: 'Drenaje temporal de la vía biliar principal tras una coledocotomía (extracción de cálculos del colédoco), dejando una vía de acceso para realizar una colangiografía postoperatoria.',
      en: 'Temporary drainage of the common bile duct after choledochotomy (removal of common bile duct stones), leaving an access route for postoperative cholangiography.',
    ),
    tip: LocalizedText(
      ca: 'Abans de retirar-lo es pot fer una colangiografia de control a través seu, injectant contrast per comprovar que la via biliar és permeable.',
      es: 'Antes de retirarlo se puede realizar una colangiografía de control a través de él, inyectando contraste para comprobar que la vía biliar es permeable.',
      en: 'Before removal, a check cholangiogram can be performed through it, injecting contrast to confirm the bile duct is patent.',
    ),
  ),
  Instrument(
    id: 'fijador-malla',
    isNew: true,
    name: LocalizedText(ca: 'Fixador de malla herniària (grapadora helicoidal)', es: 'Fijador de malla herniaria (grapadora helicoidal)', en: 'Hernia mesh fixation device (tacker)'),
    category: InstrumentCategory.especiales,
    aliases: ['Hernia tacker', 'ProTack (Medtronic)', 'AbsorbaTack (Medtronic)'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Dispositiu llarg i tubular, d\'ús laparoscòpic o obert, que dispara grapes helicoïdals (de titani o reabsorbibles) des de la punta.',
      es: 'Dispositivo largo y tubular, de uso laparoscópico o abierto, que dispara grapas helicoidales (de titanio o reabsorbibles) desde la punta.',
      en: 'Long, tubular device, used laparoscopically or in open surgery, that fires helical tacks (titanium or absorbable) from its tip.',
    ),
    use: LocalizedText(
      ca: 'Fixació d\'una malla protèsica a la paret abdominal en la reparació d\'hèrnies (inguinal, ventral, incisional), evitant-ne el desplaçament.',
      es: 'Fijación de una malla protésica a la pared abdominal en la reparación de hernias (inguinal, ventral, incisional), evitando su desplazamiento.',
      en: 'Securing a prosthetic mesh to the abdominal wall during hernia repair (inguinal, ventral, incisional), preventing it from shifting.',
    ),
    tip: LocalizedText(
      ca: 'Les grapes es col·loquen a la perifèria de la malla, evitant zones properes a nervis o vasos per no causar dolor crònic.',
      es: 'Las grapas se colocan en la periferia de la malla, evitando zonas próximas a nervios o vasos para no causar dolor crónico.',
      en: 'Tacks are placed around the periphery of the mesh, avoiding areas near nerves or vessels to prevent chronic pain.',
    ),
  ),

