      es: 'Tijeras de mango largo con hojas aisladas conectables a un generador de electrocirugía monopolar, de manera que pueden coagular y cortar con el mismo instrumento.',
      en: 'Long-shafted scissors with insulated blades that can be connected to a monopolar electrosurgical generator, allowing the same instrument to coagulate and cut.',
