  Instrument(
    id: 'osteotomo',
    isNew: true,
    name: LocalizedText(ca: 'Osteòtom', es: 'Osteótomo', en: 'Osteotome'),
    category: InstrumentCategory.corte,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Bone chisel', 'Lambotte osteotome'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Instrument en forma de falca, amb la vora tallant esmolada per ambdós costats (bisell doble), dissenyat per tallar, dividir o modelar teixit ossi.',
      es: 'Instrumento en forma de cuña, con el filo afilado por ambos lados (bisel doble), diseñado para cortar, dividir o modelar tejido óseo.',
      en: 'A wedge-shaped instrument with a cutting edge beveled on both sides, designed to cut, divide or shape bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza, normalment colpejat amb un martell quirúrgic, per tallar o remodelar l\'os durant osteotomies, artroplàsties i cirurgia de fractures.',
      es: 'Se utiliza, normalmente golpeado con un martillo quirúrgico, para cortar o remodelar el hueso durante osteotomías, artroplastias y cirugía de fracturas.',
      en: 'Struck with a surgical mallet, it is used to cut or reshape bone during osteotomies, joint replacement surgery and fracture surgery.',
    ),
    tip: LocalizedText(
      ca: 'A diferència d\'un cisell ossi d\'un sol bisell, l\'osteòtom té bisell a ambdós costats, cosa que ajuda a que el tall segueixi una línia més recta.',
      es: 'A diferencia de un escoplo óseo de un solo bisel, el osteótomo está biselado por ambos lados, lo que ayuda a que el corte siga una línea más recta.',
      en: 'Unlike a single-beveled bone chisel, an osteotome is beveled on both sides, which helps it cut in a straighter line.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/0/08/Osteotome.1ger.jpg',
      license: 'Public Domain',
      attribution: 'Gerhard Iglhaut (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Osteotome.1ger.jpg',
    ),
  ),
  Instrument(
    id: 'gubia-osea',
