    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça robusta de doble acció amb mordasses tallants i còncaves, dissenyada per rosegar i retallar petits fragments d\'os.',
      es: 'Pinza robusta de doble acción con mordazas cortantes y cóncavas, diseñada para morder y recortar pequeños fragmentos de hueso.',
      en: 'A sturdy double-action forceps with sharp, cup-shaped jaws designed to bite away and trim small fragments of bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per retirar vores òssies, osteòfits o fragments petits en cirurgia ortopèdica, de columna i neuroquirúrgica, per exemple en laminectomies o en la preparació de vores per a empelts.',
      es: 'Se utiliza para retirar bordes óseos, osteofitos o fragmentos pequeños en cirugía ortopédica, de columna y neuroquirúrgica, por ejemplo en laminectomías o en la preparación de bordes para injertos.',
      en: 'Used to remove bone edges, osteophytes or small fragments in orthopedic, spine and neurosurgical procedures, such as laminectomy or preparing bone edges for grafting.',
    ),
  ),
  Instrument(
    id: 'sierra-gigli',
    isNew: true,
    name: LocalizedText(ca: 'Serra de Gigli', es: 'Sierra de Gigli', en: 'Gigli saw'),
    category: InstrumentCategory.corte,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Gigli wire saw'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Serra manual flexible formada per un filferro trenat amb vores tallants, que s\'acciona estirant-la endavant i endarrere amb un mànec a cada extrem.',
      es: 'Sierra manual flexible formada por un alambre trenzado con bordes cortantes, que se acciona tirando de ella hacia delante y atrás con un mango en cada extremo.',
      en: 'A flexible manual saw made of twisted wire with cutting edges, operated by pulling it back and forth using a handle at each end.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per seccionar os de manera controlada en amputacions, osteotomies i reseccions òssies, especialment en espais reduïts on no hi cap una serra rígida.',
      es: 'Se utiliza para seccionar hueso de forma controlada en amputaciones, osteotomías y resecciones óseas, especialmente en espacios reducidos donde no cabe una sierra rígida.',
      en: 'Used to cut bone in a controlled way during amputations, osteotomies and bone resections, especially in confined spaces where a rigid saw cannot reach.',
    ),
    tip: LocalizedText(
      ca: 'Com que no necessita cap font d\'energia i talla en una franja molt estreta, continua sent útil quan una serra rígida no es pot angular en un espai reduït.',
      es: 'Como no necesita ninguna fuente de energía y corta en una franja muy estrecha, sigue siendo útil cuando una sierra rígida no puede angularse en un espacio reducido.',
      en: 'Because it needs no power source and cuts in a narrow track, it remains useful when a rigid saw cannot be angled into a confined space.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/ba/Gigli_Saw.jpg',
      license: 'CC BY-SA 4.0',
      attribution: 'Z22 (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Gigli_Saw.jpg',
    ),
  ),
  Instrument(
    id: 'separador-hohmann',
    isNew: true,
    name: LocalizedText(ca: 'Separador de Hohmann', es: 'Separador de Hohmann', en: 'Hohmann retractor'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Hohmann elevator'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador de mà amb un mànec llarg i una pala corba o angulada, la punta de la qual s\'encaixa contra l\'os.',
      es: 'Separador de mano con un mango largo y una pala curva o angulada, cuya punta se encaja contra el hueso.',
      en: 'A handheld retractor with a long handle and a curved or angled blade whose tip hooks against bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per separar músculs i parts toves de l\'os i exposar el camp quirúrgic en cirurgia de maluc, genoll, pelvis i fractures d\'ossos llargs.',
      es: 'Se utiliza para separar músculos y partes blandas del hueso y exponer el campo quirúrgico en cirugía de cadera, rodilla, pelvis y fracturas de huesos largos.',
      en: 'Used to retract muscle and soft tissue away from bone to expose the surgical field in hip, knee, pelvic and long-bone fracture surgery.',
    ),
    tip: LocalizedText(
      ca: 'Es fabrica en moltes amplades i corbatures de pala; triar la que s\'adapta millor al contorn de l\'os redueix el risc de lesionar les parts toves amb la punta.',
      es: 'Se fabrica en muchos anchos y curvaturas de pala; elegir la que mejor se adapta al contorno del hueso reduce el riesgo de lesionar las partes blandas con la punta.',
      en: 'It comes in many blade widths and curvatures; choosing one that matches the bone\'s contour reduces the risk of soft-tissue injury from the tip.',
    ),
  ),
  Instrument(
    id: 'separador-gelpi',
