      es: 'Se utiliza para mantener abierta una incisión sin necesidad de que un ayudante la sujete, frecuente en cirugía ortopédica, de columna y ginecológica.',
      en: 'Used to hold an incision open without an assistant having to hold it, commonly used in orthopedic, spine and gynecologic surgery.',
    ),
