  Instrument(
    id: 'aguja-kirschner',
    isNew: true,
    name: LocalizedText(ca: 'Agulla de Kirschner (filferro de Kirschner)', es: 'Aguja de Kirschner (alambre de Kirschner)', en: 'Kirschner wire (K-wire)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['K-wire'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Filferro d\'acer inoxidable llis, amb la punta esmolada i de diàmetre petit (normalment per sota dels 2-3 mm).',
      es: 'Alambre de acero inoxidable liso, con la punta afilada y de diámetro pequeño (normalmente por debajo de los 2-3 mm).',
      en: 'A smooth, sharpened stainless-steel pin of small diameter (typically under about 2-3 mm).',
    ),
    use: LocalizedText(
      ca: 'S\'introdueix a través de l\'os, amb trepant manual o elèctric, per a la fixació percutània temporal de fractures petites (mà, canell, peu) o com a ancoratge per a tracció esquelètica.',
      es: 'Se introduce a través del hueso, con taladro manual o eléctrico, para la fijación percutánea temporal de fracturas pequeñas (mano, muñeca, pie) o como anclaje para tracción esquelética.',
      en: 'Driven through bone with a hand or power drill, it provides temporary percutaneous fixation of small fractures (hand, wrist, foot) or serves as an anchor for skeletal traction.',
    ),
    tip: LocalizedText(
      ca: 'Quan s\'utilitza per a fixació temporal, les agulles de Kirschner es solen retirar al cap d\'unes quatre setmanes, un cop ha avançat prou la consolidació.',
      es: 'Cuando se usan para fijación temporal, las agujas de Kirschner suelen retirarse al cabo de unas cuatro semanas, una vez ha avanzado suficientemente la consolidación.',
      en: 'When used for temporary fixation, K-wires are typically removed around four weeks later, once healing has progressed enough.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/a/a6/K-wire%2C_Kirschner_wire.png',
      license: 'CC BY-SA 4.0',
      attribution: 'Medin a.s., Czech Republic (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:K-wire,_Kirschner_wire.png',
    ),
  ),
  Instrument(
