      es: 'Se inserta a través del hueso (p. ej. tibia o fémur) para aplicar tracción esquelética o como elemento temporal de fijación en fracturas de huesos largos.',
      en: 'Inserted through bone (e.g. tibia or femur) to apply skeletal traction or as a temporary fixation element in long-bone fractures.',
    ),
    tip: LocalizedText(
      ca: 'Un clau col·locat a la tíbia proximal és una manera habitual d\'aplicar tracció esquelètica en fractures de la diàfisi femoral.',
      es: 'Un clavo colocado en la tibia proximal es una forma habitual de aplicar tracción esquelética en fracturas de la diáfisis femoral.',
      en: 'A pin placed in the proximal tibia is a common way to apply skeletal traction for femoral shaft fractures.',
    ),
    image: InstrumentImage(
