    name: LocalizedText(ca: 'Estrep de tracció (arc de Kirschner)', es: 'Estribo de tracción (arco de Kirschner)', en: 'Traction bow (Kirschner bow)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Kirschner bow', 'K-bow', 'Böhler stirrup'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Estructura metàl·lica en forma d\'U amb un mecanisme de tensió als extrems, que es fixa a un clau de Steinmann o una agulla de Kirschner.',
      es: 'Estructura metálica en forma de U con un mecanismo de tensión en los extremos, que se fija a un clavo de Steinmann o una aguja de Kirschner.',
      en: 'A U-shaped metal frame with a tensioning mechanism at each end that attaches to a Steinmann pin or Kirschner wire.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per tensar l\'agulla o el clau que travessa l\'os i penjar-hi els pesos de la tracció esquelètica, evitant que es doblegui.',
      es: 'Se utiliza para tensar la aguja o el clavo que atraviesa el hueso y colgar de él los pesos de la tracción esquelética, evitando que se doble.',
      en: 'Used to tension the wire or pin passing through the bone and attach the weights of skeletal traction, keeping it from bending.',
    ),
  ),
  Instrument(
    id: 'tornillo-oseo',
    isNew: true,
    name: LocalizedText(ca: 'Cargol ossi (cortical / esponjós)', es: 'Tornillo óseo (cortical / esponjoso)', en: 'Bone screw (cortical / cancellous)'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Cortical screw', 'Cancellous screw', 'AO screw'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Implant metàl·lic roscat; el cortical té una rosca fina i poc profunda, i l\'esponjós una rosca més ampla i profunda per agafar-se a l\'os trabecular.',
      es: 'Implante metálico roscado; el cortical tiene una rosca fina y poco profunda, y el esponjoso una rosca más ancha y profunda para agarrarse al hueso trabecular.',
      en: 'A threaded metal implant; the cortical type has a fine, shallow thread, while the cancellous type has a wider, deeper thread to grip trabecular (spongy) bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per fixar fragments ossis entre si o per subjectar plaques d\'osteosíntesi sobre l\'os en cirurgia de fractures i ortopèdica.',
      es: 'Se utiliza para fijar fragmentos óseos entre sí o para sujetar placas de osteosíntesis sobre el hueso en cirugía de fracturas y ortopédica.',
      en: 'Used to fix bone fragments to each other or to secure osteosynthesis plates onto bone in fracture and orthopedic surgery.',
    ),
    tip: LocalizedText(
      ca: 'Els cargols esponjosos solen tenir rosca parcial, de manera que en estrènyer-los comprimeixen els fragments entre si en comptes de només fixar-los al lloc.',
      es: 'Los tornillos esponjosos suelen ser de rosca parcial, de modo que al apretarlos comprimen los fragmentos entre sí en lugar de solo fijarlos en su sitio.',
      en: 'Cancellous screws are often partially threaded, so tightening them compresses the fragments together instead of just anchoring in place.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/b/b8/Cancellous_screw.jpg',
      license: 'CC BY-SA 3.0',
      attribution: 'Netha Hussain (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Cancellous_screw.jpg',
    ),
  ),
  Instrument(
    id: 'calibrador-profundidad',
    isNew: true,
    name: LocalizedText(ca: 'Calibrador de profunditat', es: 'Calibrador de profundidad', en: 'Depth gauge'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Depth gauge probe'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Instrument en forma de vareta amb un ganxo a la punta i una escala mil·limetrada, que s\'introdueix dins un forat perforat a l\'os.',
      es: 'Instrumento en forma de varilla con un gancho en la punta y una escala milimetrada, que se introduce dentro de un orificio perforado en el hueso.',
      en: 'A rod-shaped instrument with a hooked tip and a millimeter scale, inserted into a drilled hole in the bone.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per mesurar la profunditat d\'un forat perforat a l\'os i determinar la longitud correcta del cargol que s\'hi col·locarà.',
      es: 'Se utiliza para medir la profundidad de un orificio perforado en el hueso y determinar la longitud correcta del tornillo que se colocará.',
      en: 'Used to measure the depth of a drilled bone hole and determine the correct length of screw to be inserted.',
    ),
    tip: LocalizedText(
      ca: 'La precisió de la mesura millora amb l\'experiència, per això sovint es torna a comprovar la lectura abans de triar un cargol llarg.',
      es: 'La precisión de la medida mejora con la experiencia, por eso a menudo se vuelve a comprobar la lectura antes de elegir un tornillo largo.',
      en: 'Measurement accuracy improves with experience, so the reading is often double-checked before picking a long screw.',
    ),
  ),
  Instrument(
    id: 'torniquete-neumatico',
    isNew: true,
    name: LocalizedText(ca: 'Torniquet pneumàtic quirúrgic', es: 'Torniquete neumático quirúrgico', en: 'Pneumatic surgical tourniquet'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Pneumatic tourniquet system', 'Automated tourniquet'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip format per un maniguet inflable que envolta l\'extremitat, connectat a una unitat de control que l\'infla i en regula electrònicament la pressió.',
      es: 'Equipo formado por un manguito inflable que rodea la extremidad, conectado a una unidad de control que lo infla y regula electrónicamente la presión.',
      en: 'A device consisting of an inflatable cuff wrapped around the limb, connected to a control unit that inflates it and electronically regulates the pressure.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per ocloure temporalment la circulació d\'una extremitat i obtenir un camp quirúrgic pràcticament exsangüe durant cirurgia ortopèdica, de mà o de peu.',
      es: 'Se utiliza para ocluir temporalmente la circulación de una extremidad y obtener un campo quirúrgico prácticamente exangüe durante cirugía ortopédica, de mano o de pie.',
      en: 'Used to temporarily occlude blood flow to a limb, producing a largely bloodless surgical field during orthopedic, hand or foot surgery.',
    ),
    tip: LocalizedText(
      ca: 'Les unitats modernes amb control per microprocessador regulen la pressió del maniguet en temps real i en vigilen el temps d\'inflat per ajudar a limitar el risc de lesió nerviosa o tissular.',
      es: 'Las unidades modernas con control por microprocesador regulan la presión del manguito en tiempo real y vigilan el tiempo de inflado para ayudar a limitar el riesgo de lesión nerviosa o tisular.',
      en: 'Modern microprocessor-controlled units regulate cuff pressure in real time and track inflation time to help limit the risk of nerve or tissue injury.',
    ),
    image: InstrumentImage(
      url: 'https://upload.wikimedia.org/wikipedia/commons/5/5c/Modern_tourniquet_system_attached_to_a_modern_wide_contour_cuff.jpg',
      license: 'CC BY-SA 3.0 / GFDL 1.2+',
      attribution: 'Mgebert (via Wikimedia Commons)',
      sourceUrl: 'https://commons.wikimedia.org/wiki/File:Modern_tourniquet_system_attached_to_a_modern_wide_contour_cuff.jpg',
    ),
  ),
  Instrument(
    id: 'artroscopio',
    isNew: true,
    name: LocalizedText(ca: 'Artroscopi', es: 'Artroscopio', en: 'Arthroscope'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Arthroscopy scope'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Tub prim i rígid amb un sistema òptic i de llum (sovint acoblat a una microcàmera), que es connecta a un monitor de vídeo.',
      es: 'Tubo fino y rígido con un sistema óptico y de luz (a menudo acoplado a una microcámara), que se conecta a un monitor de vídeo.',
      en: 'A thin, rigid tube with an optical and light system (usually coupled to a small camera) that connects to a video monitor.',
    ),
    use: LocalizedText(
      ca: 'S\'introdueix a través d\'una petita incisió per visualitzar l\'interior d\'una articulació (genoll, espatlla, maluc, turmell) i guiar procediments mínimament invasius.',
      es: 'Se introduce a través de una pequeña incisión para visualizar el interior de una articulación (rodilla, hombro, cadera, tobillo) y guiar procedimientos mínimamente invasivos.',
      en: 'Inserted through a small incision to visualize the inside of a joint (knee, shoulder, hip, ankle) and guide minimally invasive procedures.',
    ),
