  Instrument(
    id: 'mesa-traccion-ortopedica',
    isNew: true,
    name: LocalizedText(ca: 'Taula de tracció ortopèdica (taula de fractures)', es: 'Mesa de tracción ortopédica (mesa de fracturas)', en: 'Orthopedic traction table (fracture table)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['Fracture table', 'Hana table'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Taula quirúrgica especialitzada amb suports per a les cames que permeten aplicar i mantenir tracció longitudinal de manera controlada durant la intervenció.',
      es: 'Mesa quirúrgica especializada con soportes para las piernas que permiten aplicar y mantener tracción longitudinal de forma controlada durante la intervención.',
      en: 'A specialized operating table with leg supports that allow controlled longitudinal traction to be applied and maintained throughout the procedure.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza en cirurgia de fractures de fèmur i maluc (p. ex. enclavat endomedul·lar, artroplàstia per via anterior) per facilitar la reducció indirecta i mantenir-la durant el procediment.',
      es: 'Se utiliza en cirugía de fracturas de fémur y cadera (p. ej. enclavado endomedular, artroplastia por vía anterior) para facilitar la reducción indirecta y mantenerla durante el procedimiento.',
      en: 'Used in femur and hip fracture surgery (e.g. intramedullary nailing, anterior-approach arthroplasty) to facilitate indirect fracture reduction and maintain it throughout the procedure.',
    ),
    tip: LocalizedText(
      ca: 'Les taules de tracció poden provocar lesió per pressió al perineu o lesió nerviosa per estirament si no es vigila amb cura la posició i la força de tracció.',
      es: 'Las mesas de tracción pueden provocar lesión por presión en el periné o lesión nerviosa por estiramiento si no se vigila con cuidado la posición y la fuerza de tracción.',
      en: 'Traction tables can cause pressure injury to the perineum or nerve stretch injury if positioning and traction force are not checked carefully.',
    ),
  ),
  Instrument(
    id: 'arco-c',
    isNew: true,
    name: LocalizedText(ca: 'Arc en C (fluoroscòpia intraoperatòria)', es: 'Arco en C (fluoroscopia intraoperatoria)', en: 'C-arm (intraoperative fluoroscopy)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.ortopediaTrauma,
    aliases: ['C-arm fluoroscope', 'Mobile fluoroscopy unit'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Equip de raigs X mòbil amb un braç en forma de C que allotja l\'emissor i el detector d\'imatge en extrems oposats, i que permet obtenir imatges en temps real.',
      es: 'Equipo de rayos X móvil con un brazo en forma de C que aloja el emisor y el detector de imagen en extremos opuestos, y que permite obtener imágenes en tiempo real.',
      en: 'A mobile X-ray unit with a C-shaped arm holding the emitter and image detector at opposite ends, providing real-time imaging.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza durant la cirurgia per comprovar en temps real la reducció de la fractura, la posició dels implants (claus, plaques, cargols) i l\'alineació òssia.',
      es: 'Se utiliza durante la cirugía para comprobar en tiempo real la reducción de la fractura, la posición de los implantes (clavos, placas, tornillos) y la alineación ósea.',
      en: 'Used during surgery to check fracture reduction, implant position (nails, plates, screws) and bone alignment in real time.',
    ),
    tip: LocalizedText(
      ca: 'Com que utilitza radiació ionitzant, l\'equip quirúrgic aplica mesures de temps, distància i protecció (davantals i protectors tiroidals de plom) per minimitzar l\'exposició quan calen diverses exposicions seguides.',
      es: 'Como utiliza radiación ionizante, el equipo quirúrgico aplica medidas de tiempo, distancia y protección (delantales y protectores tiroideos de plomo) para minimizar la exposición cuando hacen falta varias exposiciones seguidas.',
      en: 'Because it uses ionizing radiation, staff follow time, distance and shielding practices (lead aprons, thyroid shields) to minimize exposure when several exposures are needed in a row.',
    ),
  ),

