  Instrument(
    id: 'pinza-kerrison',
    isNew: true,
    name: LocalizedText(ca: 'Pinça de Kerrison', es: 'Pinza de Kerrison', en: 'Kerrison rongeur'),
    category: InstrumentCategory.corte,
    specialty: Specialty.neurocirugia,
    aliases: ['Kerrison punch', 'Kerrison laminectomy rongeur', 'pinza sacabocados', 'pinza gubia de Kerrison'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça de tall amb una placa fixa a la punta i una fulla que llisca i secciona l\'os en prémer el mànec; existeix en diverses amplades i angulacions (recta, cap amunt o cap avall).',
      es: 'Pinza de corte con una placa fija en la punta y una cuchilla deslizante que secciona el hueso al apretar el mango; existe en distintas anchuras y angulaciones (recta, hacia arriba o hacia abajo).',
      en: 'A punch-type rongeur with a fixed distal footplate and a sliding blade that bites through bone as the handle is squeezed; available in multiple widths and angulations (straight, up-biting, down-biting).',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per retirar làmina vertebral i marges ossis en laminectomies, laminotomies i foraminotomies, i per ampliar craniectomies; és un dels instruments més emprats en cirurgia d\'estenosi espinal i hèrnies discals.',
      es: 'Se usa para retirar lámina vertebral y bordes óseos en laminectomías, laminotomías y foraminotomías, y para ampliar craniectomías; es uno de los instrumentos más empleados en cirugía de estenosis espinal y hernias discales.',
      en: 'Used to remove vertebral lamina and bone edges during laminectomy, laminotomy and foraminotomy, and to enlarge craniectomy margins; one of the most frequently used instruments in spinal stenosis and disc herniation surgery.',
    ),
    tip: LocalizedText(
      ca: 'Cal avançar la fulla amb control i sense tensionar la duramare subjacent, ja que la durotomia és una complicació ben descrita amb aquest instrument.',
      es: 'Conviene avanzar la cuchilla con control y sin tensionar la duramadre subyacente, ya que la durotomía es una complicación bien descrita con este instrumento.',
      en: 'Advance the blade under control and without tenting the underlying dura, since durotomy is a well-described complication of this instrument.',
    ),
  ),
  Instrument(
    id: 'pinza-hipofisaria',
    isNew: true,
    name: LocalizedText(ca: 'Pinça hipofisària (pinça de disc)', es: 'Pinza hipofisaria (pinza de disco)', en: 'Pituitary rongeur (disc rongeur)'),
    category: InstrumentCategory.corte,
    specialty: Specialty.neurocirugia,
    aliases: ['Spurling pituitary rongeur', 'pinza de Spurling', 'disc forceps', 'cup rongeur'],
    icon: 'cut',
    description: LocalizedText(
      ca: 'Pinça tipus "pistol-grip" amb dues mandíbules còncaves (en forma de cullereta) que tallen i arrenquen petits fragments de teixit en tancar-se; disponible en versions recta, cap amunt i cap avall i diverses mides de mandíbula.',
      es: 'Pinza tipo "pistol-grip" con dos mandíbulas cóncavas (en forma de cuchara) que cortan y arrancan pequeños fragmentos de tejido al cerrarse; disponible en versiones recta, hacia arriba y hacia abajo y distintos tamaños de mandíbula.',
      en: 'A pistol-grip instrument with two cup-shaped hinged jaws that shear and pull away small fragments of tissue as they close; available in straight, up-biting and down-biting configurations and several jaw sizes.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per extreure fragments de disc intervertebral (nucli pulpós) en microdiscectomies lumbars i per a dissecció de teixit tou en cirurgia transesfenoïdal hipofisària, d\'on prové el seu nom.',
      es: 'Se usa para extraer fragmentos de disco intervertebral (núcleo pulposo) en microdiscectomías lumbares y para disección de tejido blando en cirugía transesfenoidal hipofisaria, de donde proviene su nombre.',
      en: 'Used to remove intervertebral disc fragments (nucleus pulposus) during lumbar microdiscectomy and for soft-tissue dissection in transsphenoidal pituitary surgery, the origin of its name.',
    ),
  ),
  Instrument(
    id: 'disector-penfield',
    isNew: true,
    name: LocalizedText(ca: 'Disector de Penfield', es: 'Disector de Penfield', en: 'Penfield dissector'),
    category: InstrumentCategory.diseccion,
    specialty: Specialty.neurocirugia,
