      es: 'Dispositivo portátil alimentado por batería, con una sonda bipolar de dos puntas separadas unos milímetros, que aplica una corriente constante ajustable directamente sobre la superficie cortical.',
      en: 'A portable, battery-powered device with a bipolar probe whose two tips sit a few millimeters apart, delivering an adjustable constant current directly onto the cortical surface.',
    ),
    use: LocalizedText(
      ca: 'S\'utilitza per mapar intraoperatòriament àrees corticals eloqüents (motores, sensitives o del llenguatge) durant craniotomies despertes o sota anestèsia, per maximitzar la resecció tumoral preservant la funció.',
      es: 'Se utiliza para mapear intraoperatoriamente áreas corticales elocuentes (motoras, sensitivas o del lenguaje) durante craneotomías despiertas o bajo anestesia, para maximizar la resección tumoral preservando la función.',
      en: 'Used to intraoperatively map eloquent cortical areas (motor, sensory or language) during awake or anesthetized craniotomy, maximizing tumor resection while preserving function.',
    ),
  ),
  Instrument(
    id: 'cabezal-fijacion-mayfield',
    isNew: true,
    name: LocalizedText(ca: 'Capçal de fixació de Mayfield', es: 'Cabezal de fijación de Mayfield', en: 'Mayfield skull clamp (head holder)'),
    category: InstrumentCategory.equipos,
    specialty: Specialty.neurocirugia,
    aliases: ['Mayfield clamp', 'Mayfield head holder', 'three-pin skull clamp'],
    icon: 'tool',
    description: LocalizedText(
      ca: 'Sistema format per una pinça amb tres pues (dues a un costat, una a l\'altre amb cargol dinamomètric) i un braç articulat que s\'ancora a la taula quirúrgica.',
      es: 'Sistema formado por una pinza con tres puntas (dos a un lado, una al otro con tornillo dinamométrico) y un brazo articulado que se ancla a la mesa quirúrgica.',
      en: 'A system made of a three-pin clamp (two pins on one side, one on the other fitted with a torque screw) and an articulated arm that anchors to the operating table.',
    ),
    use: LocalizedText(
      ca: 'Immobilitza rígidament el crani del pacient respecte a la taula d\'operacions durant craniotomies i certs abordatges cervicals posteriors, permetent precisió amb microscopi o neuronavegació.',
      es: 'Inmoviliza rígidamente el cráneo del paciente respecto a la mesa de operaciones durante craneotomías y ciertos abordajes cervicales posteriores, permitiendo precisión con microscopio o neuronavegación.',
      en: 'Rigidly immobilizes the patient\'s skull relative to the operating table during craniotomies and certain posterior cervical approaches, enabling precision work with the microscope or neuronavigation.',
    ),
    tip: LocalizedText(
      ca: 'En infants petits o pacients amb calota molt prima cal valorar alternatives de fixació, ja que s\'han descrit fractures cranials amb les pues del Mayfield.',
      es: 'En niños pequeños o pacientes con calota muy fina conviene valorar alternativas de fijación, ya que se han descrito fracturas craneales con las puntas del Mayfield.',
      en: 'In young children or patients with very thin calvaria, alternative fixation should be considered, as skull fractures from the Mayfield pins have been reported.',
    ),
  ),
  Instrument(
    id: 'neuroendoscopio-rigido',
