      es: 'Hilos metálicos finos y aislados que el cirujano sutura directamente sobre el epicardio de la aurícula y/o el ventrículo antes de cerrar el tórax.',
      en: 'Thin, insulated metal wires that the surgeon sutures directly onto the atrial and/or ventricular epicardium before closing the chest.',
    ),
    use: LocalizedText(
      ca: 'Es connecten a un generador extern per fer estimulació cardíaca temporal o tractar arrítmies en el postoperatori immediat de cirurgia cardíaca.',
      es: 'Se conectan a un generador externo para realizar estimulación cardíaca temporal o tratar arritmias en el postoperatorio inmediato de cirugía cardíaca.',
      en: 'They connect to an external pacemaker generator to provide temporary cardiac pacing or treat arrhythmias in the immediate postoperative period after cardiac surgery.',
    ),
  ),
  Instrument(
    id: 'palas-desfibrilacion-internas',
    isNew: true,
    name: LocalizedText(ca: 'Pales de desfibril·lació internes', es: 'Palas de desfibrilación internas', en: 'Internal defibrillation paddles'),
    category: InstrumentCategory.especiales,
    specialty: Specialty.cardiovascular,
    aliases: ['Internal defibrillation paddles', 'Internal cardiac paddles', 'Electrodos internos de desfibrilación'],
    icon: 'bolt',
    description: LocalizedText(
      ca: 'Parell d\'elèctrodes en forma de cullera, muntats cadascun sobre un mànec, dissenyats per aplicar-se directament sobre el miocardi a través del tòrax obert.',
      es: 'Par de electrodos en forma de cuchara, montados cada uno sobre un mango, diseñados para aplicarse directamente sobre el miocardio a través del tórax abierto.',
      en: 'A pair of spoon-shaped electrodes mounted on handles, designed to be applied directly to the myocardium through the open chest.',
    ),
    use: LocalizedText(
      ca: 'Desfibril·len o cardioverteixen el cor directament durant la cirurgia a cor obert, amb energies molt més baixes (10-20 J) que la desfibril·lació externa.',
      es: 'Desfibrilan o cardiovierten el corazón directamente durante la cirugía a corazón abierto, con energías mucho más bajas (10-20 J) que la desfibrilación externa.',
      en: 'They directly defibrillate or cardiovert the heart during open-heart surgery, using much lower energy (10-20 J) than external defibrillation.',
    ),
  ),
  Instrument(
    id: 'balon-contrapulsacion-intraaortico',
    isNew: true,
    name: LocalizedText(ca: 'Baló de contrapulsació intraaòrtic', es: 'Balón de contrapulsación intraaórtico', en: 'Intra-aortic balloon pump'),
