    name: LocalizedText(ca: 'Separador esternal', es: 'Separador esternal', en: 'Sternal retractor'),
    category: InstrumentCategory.separacion,
    specialty: Specialty.cardiovascular,
    aliases: ['Sternal retractor', 'Sternum spreader', 'Ankeney retractor', 'Favaloro-Morse retractor'],
    icon: 'expand',
    description: LocalizedText(
      ca: 'Separador de carraca amb dues branques que s\'obren gradualment i mantenen separades les dues meitats de l\'estèrnum després de l\'esternotomia mitjana.',
      es: 'Separador de cremallera con dos ramas que se abren gradualmente y mantienen separadas las dos mitades del esternón tras la esternotomía media.',
      en: 'A ratcheted retractor with two blades that open gradually and hold the two halves of the sternum apart after a median sternotomy.',
    ),
    use: LocalizedText(
      ca: 'Proporciona exposició del mediastí i del cor durant la revascularització coronària, la cirurgia valvular i altres intervencions per esternotomia mitjana.',
      es: 'Proporciona exposición del mediastino y del corazón durante la revascularización coronaria, la cirugía valvular y otras intervenciones por esternotomía media.',
      en: 'It provides exposure of the mediastinum and the heart during coronary revascularization, valve surgery, and other procedures performed through a median sternotomy.',
    ),
    tip: LocalizedText(
      ca: 'No s\'ha de confondre amb el separador de Finochietto: aquest obre l\'espai intercostal en toracotomies laterals, no l\'estèrnum.',
      es: 'No debe confundirse con el separador de Finochietto: este abre el espacio intercostal en toracotomías laterales, no el esternón.',
      en: 'Not to be confused with the Finochietto retractor, which spreads the intercostal space in lateral thoracotomies rather than the sternum.',
    ),
  ),
